fn effect(px: vec2<f32>) -> vec4<f32> {
    // Sideways ripple that travels down the layer with time.
    let wave = sin(px.y * u.frequency + globals.time * 6.0) * u.strength;
    let c = layer(px + vec2<f32>(wave, 0.0));
    // A tint that pulses with the frame and darkens toward the corners.
    let d = length(px / globals.canvas - vec2<f32>(0.5));
    let pulse = 0.5 + 0.5 * sin(globals.frame * 0.2);
    let tint = vec3<f32>(1.0, 0.8 + 0.2 * pulse, 1.0 - 0.3 * d);
    return vec4<f32>(c.rgb * tint, c.a);
}

