fn effect(px: vec2<f32>) -> vec4<f32> {
    // Blocks that shrink from 16 to 2 pixels as the frames go by.
    let size = max(2.0, 16.0 - globals.frame * 0.5);
    return layer((floor(px / size) + vec2<f32>(0.5)) * size);
}

